<template><PlayerPageShell title="消息通知" subtitle="公告由平台可靠投递后生成"><view v-if="messages.length" class="list"><view v-for="message in messages" :key="message.messageId" class="card" @click="read(message)"><view><text class="title">{{ message.title }}</text><text class="content">{{ message.content }}</text><text class="time">{{ formatTime(message.publishedAt || message.receivedAt) }}</text></view><text v-if="!message.readAt" class="dot"></text></view></view><view v-else class="empty">暂无消息通知</view></PlayerPageShell></template>
<script>import{getPlayerMessages,markPlayerMessageRead}from'@/api/competition-player';import PlayerPageShell from './components/PlayerPageShell.vue';import{guardCompetitionPlayerRoute}from'@/utils/competition-route-guard';export default{components:{PlayerPageShell},data:()=>({messages:[]}),async onShow(){if(!guardCompetitionPlayerRoute())return;try{this.messages=(await getPlayerMessages()).items||[]}catch(e){uni.showToast({title:e.message||'消息加载失败',icon:'none'})}},methods:{async read(message){if(!message.readAt){try{await markPlayerMessageRead(message.messageId);message.readAt=new Date().toISOString()}catch(e){uni.showToast({title:e.message||'消息状态更新失败',icon:'none'})}}},formatTime(value){return value?String(value).replace('T',' ').slice(0,16):''}}}</script>
<style scoped>.list{display:flex;flex-direction:column;gap:18rpx}.card{display:flex;justify-content:space-between;gap:18rpx;padding:30rpx;background:#fff;border-radius:20rpx}.card view{display:flex;flex:1;flex-direction:column;gap:12rpx}.title{font-size:30rpx;font-weight:700}.content{display:-webkit-box;overflow:hidden;color:#6e8099;font-size:25rpx;line-height:1.5;-webkit-box-orient:vertical;-webkit-line-clamp:2}.time{font-size:22rpx;color:#9ba8ba}.dot{width:15rpx;height:15rpx;margin-top:12rpx;border-radius:50%;background:#ea5c57}.empty{padding:48rpx;text-align:center;color:#8492a7;background:#fff;border-radius:20rpx}</style>
